-- 31-검증. 096000 적용 직후 (조회 전용). 모든 ok 가 true 여야 합니다.
SELECT no, item, actual, expected,
       CASE WHEN expected = '기록용' THEN NULL ELSE actual IS NOT DISTINCT FROM expected END AS ok
FROM (VALUES
    (1, '작성자 권한 트리거(머리글 13종, 활성)', (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_edit_rights' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs']::text[]) t)) AND tgenabled <> 'D'), '13'),
    (2, '작성자 권한 트리거(항목 12종, 활성)', (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_item_edit_rights' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t)) AND tgenabled <> 'D'), '12'),
    (3, '권한 함수 3개', ((to_regprocedure('public.enforce_daily_log_edit_rights()') IS NOT NULL)::text || '/' || (to_regprocedure('public.enforce_daily_log_item_edit_rights()') IS NOT NULL)::text || '/' || (to_regprocedure('public.daily_log_workflow_columns()') IS NOT NULL)::text), 'true/true/true'),
    (4, '조도 일지 author_user_id 컬럼(빈 값 허용)', (SELECT is_nullable FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'daily_illumination_logs' AND column_name = 'author_user_id'), 'YES'),
    (5, '조도 일지 10/15 이전 작성분 중 author_user_id 채워진 행(없어야 함)', (SELECT count(*)::text FROM public.daily_illumination_logs WHERE created_at < timestamptz '2026-10-15 00:00:00+09' AND author_user_id IS NOT NULL), '0'),
    (6, '091000·094000 유지', ((SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_approval_times' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs']::text[]) t)) AND tgenabled <> 'D') || '/' || (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_item_parent_unlocked' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t)) AND tgenabled <> 'D')), '13/12'),
    (7, '감사 트리거 유지(일지 25)', (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_audit_row_change' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t)) AND tgenabled <> 'D'), '25'),
    (8, '회사 범위 정책 유지(095000)', (SELECT count(*)::text FROM pg_policies WHERE schemaname = 'public' AND tablename = ANY (ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) AND policyname = tablename || '_org_access'), '25')
) AS v(no, item, actual, expected)
ORDER BY no;
